def predict(probe):
    # Rule 1: deduplicate characters, keeping first occurrence of each exact char [E2 aabbcc->zbc, E5 Mississippi->Lisp, E6 aAbB->zAbB]
    # Rule 2: dedup is case-sensitive / exact-char (space, digits, symbols all participate) [E8 a b c->z bc, E12 0abc0->0abc]
    # Rule 3: shift the FIRST character down by 1 iff it is a letter [E1 apple->zple, E4 Abc->Zbc, E12 a1b2c3->z1b2c3]
    #   - ASCII 'a'->'z', 'A'->'Z' (wraparound) [E2 aaaa->z, E6 ABCabc->ZBCabc]
    #   - other ASCII letters: -1 [E1 test->ses, E3 racecar->qace, E5 function->eunctio]
    #   - non-ASCII letters: -1 [E4 éclair->èclair, E10 Éclair->Èclair, Ω->Ψ, ß->Þ]
    #   - non-letters (digits, spaces, punctuation) unchanged [E2 123->123, E4 !hello->!helo, E12 321->321]
    # Rule 4: only the first character is shifted; all later chars unchanged [E1 hello->gelo, E3 Python->Oython]
    outputs = []
    for s in probe.get("inputs", []):
        seen = set()
        dedup = []
        for ch in s:
            if ch not in seen:
                seen.add(ch)
                dedup.append(ch)
        if dedup:
            c = dedup[0]
            if 'a' <= c <= 'z':
                dedup[0] = 'z' if c == 'a' else chr(ord(c) - 1)
            elif 'A' <= c <= 'Z':
                dedup[0] = 'Z' if c == 'A' else chr(ord(c) - 1)
            elif c.isalpha():
                dedup[0] = chr(ord(c) - 1)  # ? non-ASCII letters: -1, no wraparound observed
        outputs.append(''.join(dedup))
    return {"outputs": outputs}
